Now my own instruction-following prompts: generic writing tasks combined with 1–3 verifiable constraints (word limits, paragraph/bullet counts, lowercase/uppercase, no commas, quotes, postscript, title, keywords, JSON, sections, letter bans, end phrase). I'll avoid contradictory combinations, write a strict checker for each constraint, and split them A/B. I'll print one example and run the checker on a hand-written answer as a sanity test.

```python
# Hypothesis: none (building own instruction-following prompts with strict checkers).
import re
irng = random.Random(99)
tasks = ["Write a short story about a lighthouse keeper who finds an old map.",
 "Write a product description for a solar-powered backpack.",
 "Write a letter to a neighbor asking them to keep their dog quiet at night.",
 "Explain to a ten-year-old why the sky changes color at sunset.",
 "Write a review of a small family-run bakery you visited.",
 "Describe a typical day in the life of a beekeeper.",
 "Write a speech for the opening of a new public library.",
 "Give advice to a student who is nervous about their first job interview.",
 "Write a poem about a city during a thunderstorm.",
 "Summarize the benefits and drawbacks of working from home.",
 "Write a travel guide entry for a fictional mountain village called Velmora.",
 "Write an email to a team announcing a change in the weekly meeting time.",
 "Describe how to plant and care for tomato seedlings.",
 "Write a dialogue between a robot and a cat who meet in an empty kitchen.",
 "Write a pitch for a mobile app that helps people share leftover food.",
 "Explain the rules of a board game you invent, called Riverstones.",
 "Write a diary entry of an astronaut on her first night in orbit.",
 "Write a short essay on why people enjoy collecting things.",
 "Write a complaint to a train company about a delayed journey.",
 "Describe the history of an imaginary invention, the folding umbrella-chair.",
 "Write a motivational message for a running club before a marathon.",
 "Write a recipe introduction for a winter vegetable soup.",
 "Explain what a budget is and how a family might make one.",
 "Write a fairy tale about a fox who wants to learn to read.",
 "Write a job advertisement for a night-shift librarian.",
 "Describe the sounds of a forest in early morning.",
 "Write a thank-you note to a teacher who helped you learn math.",
 "Write a news report about a town that built a giant sandcastle.",
 "Explain how a bicycle gear system works.",
 "Write a debate opening statement arguing that cities should plant more trees."]
KW = ['harbor', 'lantern', 'compass', 'velvet', 'orbit', 'pebble', 'whisper', 'meadow', 'copper', 'puzzle', 'ember', 'canvas']
def words_of(s): return re.findall(r"[A-Za-z0-9']+", s)
def n_sent(s): return len([x for x in re.split(r'(?<=[.!?])\s+', s.strip()) if x.strip()])
def mk(kind):
    if kind == 'lower': return ("Your entire response should be in English, and in all lowercase letters. No capital letters are allowed.", lambda r: len(r) > 0 and r == r.lower())
    if kind == 'upper': return ("Your entire response should be in English and in all capital letters.", lambda r: len(r) > 0 and r == r.upper())
    if kind == 'nocomma': return ("Do not use any commas in your response.", lambda r: len(r) > 0 and ',' not in r)
    if kind == 'quotes': return ("Wrap your entire response in double quotation marks.", lambda r: len(r) > 1 and r.startswith('"') and r.endswith('"'))
    if kind == 'ps': return ("At the end of your response, please explicitly add a postscript starting with P.S.", lambda r: re.search(r'P\.S\.', r) is not None)
    if kind == 'title': return ("Your answer must contain a title, wrapped in double angular brackets, such as <<my title>>.", lambda r: re.search(r'<<[^\n<>]+>>', r) is not None)
    if kind == 'minw':
        n = irng.choice([150, 200, 300, 400]); return (f"Your response should contain at least {n} words.", lambda r, n=n: len(words_of(r)) >= n)
    if kind == 'maxw':
        n = irng.choice([40, 50, 60, 80]); return (f"Answer with fewer than {n} words.", lambda r, n=n: 0 < len(words_of(r)) < n)
    if kind == 'paras':
        k = irng.choice([2, 3, 4, 5]); return (f"Your response should contain exactly {k} paragraphs, separated from each other by the markdown divider ***.", lambda r, k=k: len([p for p in r.split('***') if p.strip()]) == k and r.count('***') == k-1)
    if kind == 'bullets':
        k = irng.choice([3, 4, 5]); return (f"Your answer must contain exactly {k} bullet points. Use markdown bullet points such as:\n* This is point 1.", lambda r, k=k: len(re.findall(r'^\s*[\*\-] ', r, flags=re.M)) == k)
    if kind == 'kw':
        a, b = irng.sample(KW, 2); return (f"Include the keywords '{a}' and '{b}' in your response.", lambda r, a=a, b=b: a in r.lower() and b in r.lower())
    if kind == 'freq':
        w = irng.choice(['light', 'time', 'small', 'home', 'green']); k = irng.choice([3, 4, 5])
        return (f"In your response, the word '{w}' should appear at least {k} times.", lambda r, w=w, k=k: len(re.findall(r'\b' + w + r'\b', r.lower())) >= k)
    if kind == 'json': return ("Your entire output should be wrapped in JSON format. You can use markdown ticks such as ```.", chk_json)
    if kind == 'highlight':
        k = irng.choice([2, 3]); return (f"Highlight at least {k} sections in your answer with markdown, i.e. *highlighted section*.", lambda r, k=k: len(re.findall(r'\*[^\n\*]+\*', r)) >= k)
    if kind == 'end':
        ph = irng.choice(["Is there anything else I can help with?", "Let me know if you have additional questions."])
        return (f"Finish your response with this exact phrase: {ph} No other words should follow this phrase.", lambda r, ph=ph: r.endswith(ph))
    if kind == 'sections':
        k = irng.choice([2, 3, 4]); return (f"Your response must have {k} sections. Mark the beginning of each section with SECTION X, such as: SECTION 1.", lambda r, k=k: len(re.findall(r'SECTION\s+\d+', r)) == k)
    if kind == 'maxsent':
        k = irng.choice([3, 4, 5]); return (f"Your response should contain at most {k} sentences.", lambda r, k=k: 0 < n_sent(r) <= k)
    if kind == 'noletter':
        L = irng.choice(['e', 'a', 'o']); return (f"Do not use the letter '{L}' anywhere in your response.", lambda r, L=L: len(r) > 0 and L not in r.lower())
    if kind == 'placeholder':
        k = irng.choice([2, 3]); return (f"The response must contain at least {k} placeholders represented by square brackets, such as [name].", lambda r, k=k: len(re.findall(r'\[[^\[\]\n]+\]', r)) >= k)
    if kind == 'two':
        return ("Give two different responses. Responses and only responses should be separated by 6 asterisk symbols: ******.", lambda r: len([p for p in r.split('******') if p.strip()]) == 2 and r.count('******') == 1)
def chk_json(r):
    s = r.strip()
    s = re.sub(r'^' + '`'*3 + r'(json|JSON)?\s*', '', s); s = re.sub(r'\s*' + '`'*3 + r'$', '', s)
    try: json.loads(s); return True
    except Exception: return False
kinds = ['lower','upper','nocomma','quotes','ps','title','minw','maxw','paras','bullets','kw','freq','json','highlight','end','sections','maxsent','noletter','placeholder','two']
conflict = {('lower','upper'),('lower','ps'),('lower','sections'),('lower','end'),('lower','title'),('upper','end'),('upper','noletter'),
            ('json','paras'),('json','bullets'),('json','quotes'),('json','ps'),('json','title'),('json','end'),('json','sections'),('json','two'),('json','highlight'),
            ('quotes','end'),('quotes','ps'),('quotes','two'),('minw','maxw'),('minw','maxsent'),('paras','sections'),('paras','two'),('sections','two'),('bullets','maxsent'),
            ('end','ps'),('end','two'),('noletter','ps'),('noletter','end'),('noletter','kw'),('noletter','freq'),('noletter','sections'),('noletter','json'),('noletter','title'),('noletter','placeholder'),('noletter','two'),('noletter','paras'),('noletter','bullets'),('noletter','highlight'),('maxw','paras'),('maxw','sections'),('maxw','two'),('maxsent','paras'),('maxsent','two'),('maxsent','sections'),('upper','sections'),('lower','placeholder'),('upper','placeholder')}
def ok(c): return all((a, b) not in conflict and (b, a) not in conflict for a in c for b in c if a != b)
if_items = []
while len(if_items) < 160:
    t = irng.choice(tasks); k = irng.choice([1, 2, 2, 3])
    c = irng.sample(kinds, k)
    if not ok(c): continue
    ins = [mk(kd) for kd in c]
    if_items.append({'id': 'i%03d' % len(if_items), 'prompt': t + ' ' + ' '.join(s for s, _ in ins), 'kinds': c, 'checks': [f for _, f in ins]})
print(len(if_items), collections.Counter(len(it['kinds']) for it in if_items))
print(if_items[0]['prompt'][:400], if_items[0]['kinds'])
print(mk('two')[1]('first answer here\n******\nsecond one'), chk_json('`'*3 + 'json\n{"a": 1}\n' + '`'*3), mk('paras')[1]('a\n***\nb') )
```

