```python
# Hypothesis: none (text-based IF checker file; verify agreement with in-kernel checkers on P1 answers).
if_code = r'''
import re, json
def words_of(s): return re.findall(r"[A-Za-z0-9']+", s)
def n_sent(s): return len([x for x in re.split(r'(?<=[.!?])\s+', s.strip()) if x.strip()])
def chk_json(r):
    s = r.strip(); s = re.sub(r'^' + '`'*3 + r'(json|JSON)?\s*', '', s); s = re.sub(r'\s*' + '`'*3 + r'$', '', s)
    try: json.loads(s); return True
    except Exception: return False
def check(kind, P, r):
    g = lambda pat: re.search(pat, P)
    if kind == 'lower': return len(r) > 0 and r == r.lower()
    if kind == 'upper': return len(r) > 0 and r == r.upper()
    if kind == 'nocomma': return len(r) > 0 and ',' not in r
    if kind == 'quotes': return len(r) > 1 and r.startswith('"') and r.endswith('"')
    if kind == 'ps': return re.search(r'P\.S\.', r) is not None
    if kind == 'title': return re.search(r'<<[^\n<>]+>>', r) is not None
    if kind == 'minw': return len(words_of(r)) >= int(g(r'at least (\d+) words').group(1))
    if kind == 'maxw': return 0 < len(words_of(r)) < int(g(r'fewer than (\d+) words').group(1))
    if kind == 'paras':
        k = int(g(r'exactly (\d+) paragraphs').group(1)); return len([p for p in r.split('***') if p.strip()]) == k and r.count('***') == k - 1
    if kind == 'bullets': return len(re.findall(r'^\s*[\*\-] ', r, flags=re.M)) == int(g(r'exactly (\d+) bullet points').group(1))
    if kind == 'kw':
        m = g(r"keywords '(\w+)' and '(\w+)'"); return m.group(1) in r.lower() and m.group(2) in r.lower()
    if kind == 'freq':
        m = g(r"the word '(\w+)' should appear at least (\d+) times"); return len(re.findall(r'\b' + m.group(1) + r'\b', r.lower())) >= int(m.group(2))
    if kind == 'json': return chk_json(r)
    if kind == 'highlight': return len(re.findall(r'\*[^\n\*]+\*', r)) >= int(g(r'Highlight at least (\d+) sections').group(1))
    if kind == 'end': return r.endswith(g(r'exact phrase: (.*?) No other words').group(1))
    if kind == 'sections': return len(re.findall(r'SECTION\s+\d+', r)) == int(g(r'must have (\d+) sections').group(1))
    if kind == 'maxsent': return 0 < n_sent(r) <= int(g(r'at most (\d+) sentences').group(1))
    if kind == 'noletter':
        L = g(r"use the letter '(\w)'").group(1); return len(r) > 0 and L not in r.lower()
    if kind == 'placeholder': return len(re.findall(r'\[[^\[\]\n]+\]', r)) >= int(g(r'at least (\d+) placeholders').group(1))
    if kind == 'two': return len([p for p in r.split('******') if p.strip()]) == 2 and r.count('******') == 1
    raise ValueError(kind)
def grade_if_text(answer_after_think, prompt, kinds):
    if answer_after_think is None: return 'no_close'
    r = answer_after_think.strip()
    return 'pass' if all(check(k, prompt, r) for k in kinds) else 'fail'
'''
open('/work/if_checks.py', 'w').write(if_code)
nsif = {}; exec(if_code, nsif)
agree = [nsif['grade_if_text'](after_think(r['text']), iid[r['oid']]['prompt'], iid[r['oid']]['kinds']) == r['g'] for r in g1 if r['grp'] == 'if']
print('agreement with in-kernel checkers on P1 IF answers:', sum(agree), '/', len(agree))
```

